(() => {
'use strict';const c=window.HVT;async function list(resourceId,drafts=false){let all=[],offset=0;while(true){const rows=await(drafts?c.api:c.publicApi)('/rest/v1/'+(drafts?'video_episode_drafts':'video_episodes')+'?select=*&resource_id=eq.'+encodeURIComponent(resourceId)+'&order=episode_order.asc&limit=1000&offset='+offset);all.push(...rows);if(rows.length<1000)return all;offset+=rows.length}}
const title=e=>(e.label?e.label+' '+e.number:'Phần '+e.episode_order)+(e.title?' — '+e.title:'');
async function attach(item,container,isCurrent){const host=document.createElement('section');host.className='video-series-reader';host.innerHTML='<p role="status">Đang tải các tập công khai…</p>';container.append(host);try{const rows=await list(item.id);if(!isCurrent())return;if(!rows.length){host.textContent='Bộ video chưa có tập công khai.';return}const requested=new URLSearchParams(location.search).get('episode');let index=Math.max(0,rows.findIndex(e=>e.id===requested));if(!requested&&c.currentUser?.()){try{const saved=await c.api('/rest/v1/member_activity?select=episode_id&resource_id=eq.'+encodeURIComponent(item.id)+'&limit=1');if(!isCurrent())return;const n=rows.findIndex(e=>e.id===saved[0]?.episode_id);if(n>=0)index=n}catch{}}
function draw(){window.HVTCommunity?.close();const ep=rows[index],cover=ep.inherit_cover?c.cover(item):c.cover(ep)||c.cover(item),embed=c.embed(ep.url);let media=cover?'<img class="reader-cover" src="'+c.esc(cover)+'" alt="Bìa '+c.esc(title(ep))+'">':'';if(embed)media+='<iframe src="'+c.esc(embed)+'" title="'+c.esc(title(ep))+'" allow="fullscreen; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>';else if(/\.(mp4|webm)(\?|$)/i.test(ep.url))media+='<video src="'+c.esc(ep.url)+'" controls preload="metadata"></video>';host.innerHTML='<label>Chọn Tập / Kỳ / Phẩm<select data-episode-select aria-label="Chọn tập video">'+rows.map((e,n)=>'<option value="'+n+'" '+(n===index?'selected':'')+'>'+c.esc(title(e))+'</option>').join('')+'</select></label><h3>'+c.esc(title(ep))+'</h3>'+media+'<p>'+c.esc(ep.description)+'</p><p><a class="text-link" target="_blank" rel="noopener noreferrer" href="'+c.esc(ep.url)+'">Mở nguồn video này ↗</a></p><div class="chapter-navigation"><button type="button" data-episode-step="-1" class="button secondary" '+(index===0?'disabled':'')+'>← Phần trước</button><span>'+(index+1)+' / '+rows.length+'</span><button type="button" data-episode-step="1" class="button secondary" '+(index===rows.length-1?'disabled':'')+'>Phần tiếp →</button></div>';host.querySelector('select').onchange=e=>{index=Number(e.target.value);draw()};host.querySelectorAll('[data-episode-step]').forEach(b=>b.onclick=()=>{index+=Number(b.dataset.episodeStep);draw()});window.HVTCommunity?.open(item,container);window.HVTCommunity?.episode(ep.id);}
draw();}catch{if(isCurrent())host.textContent='Chưa tải được bộ video. Kiểm tra kết nối và migration V9.'}}
window.HVTVideoSeries={list,title,attach};
})();
